const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Environment file not found: ${filePath}`);
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const env = {};

  content.split('\n').forEach(line => {
    // Skip empty lines and comments
    if (!line.trim() || line.trim().startsWith('#')) {
      return;
    }

    const match = line.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      env[key] = value;
    }
  });

  return env;
}

function getConnectionString() {
  const env = loadEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error('DATABASE_URL not found in .env.test');
  }

  return databaseUrl;
}

function connect() {
  const connectionString = getConnectionString();
  // Parse the connection string to extract host for logging (without credentials)
  const urlMatch = connectionString.match(/@([^:\/]+)/);
  const host = urlMatch ? urlMatch[1] : 'database';
  console.log(`Successfully connected to ${host}`);
}

