const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return [];
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort them alphabetically/numerically
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  return sqlFiles;
}

function main() {
  console.log('Database Migration Script');
  console.log('=========================\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\n(Dry run - no migrations were actually applied)');
}

main();

